import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    s = lines[0].strip()
    if len(lines) > 1:
        k = int(lines[1].strip())
    else:
        return

    n = len(s)
    unique_count = len(set(s))

    if n < k:
        print("impossible")
    else:
        changes_needed = max(0, k - unique_count)
        print(changes_needed)

if __name__ == "__main__":
    main()
